/**
 * Moving an issue to another project (ADR 0011): numbering, permissions,
 * quota, events, audit entry and search index.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Project } from "@/types/project";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Project;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(activityService.registerActivityListeners());
  detachers.push(searchService.registerSearchListeners());
  tenant = await createTenant("movesvc");
  other = await projectService.createProject(tenant.actors.owner, {
    orgId: tenant.org.id,
    name: "Other",
    slug: "other",
    key: "OTH",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

const create = (projectId: Project["id"], title: string) =>
  issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );

describe("issueService.moveIssueToProject", () => {
  it("renumbers into the target, retires the old number and records one event", async () => {
    await create(other.id, "Occupies OTH-1");
    const first = await create(tenant.project.id, "Move me away");
    const second = await create(tenant.project.id, "Stays behind");
    expect([first.number, second.number]).toEqual([1, 2]);

    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    const created: unknown[] = [];
    const offCreated = subscribe("issue.created", (p) => {
      created.push(p);
    });

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      toProjectId: other.id,
    });
    off();
    offCreated();

    expect(moved).toMatchObject({ id: first.id, projectId: other.id, number: 2, title: first.title });
    expect(seen).toMatchObject([
      {
        issueId: first.id,
        actorId: tenant.actors.member.userId,
        fromProjectId: tenant.project.id,
        toProjectId: other.id,
        fromNumber: 1,
        toNumber: 2,
      },
    ]);
    expect(created).toEqual([]);

    // Number 1 is retired in the source; a move back takes the next number.
    await expect(issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id)).resolves.toBe(3);
    const back = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      toProjectId: tenant.project.id,
    });
    expect(back.number).toBe(3);

    const page = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(2);
    const toOther = page.items.find((e) => e.projectId === other.id);
    expect(toOther).toMatchObject({
      subjectKind: "issue",
      subjectId: first.id,
      metadata: {
        fromProjectId: tenant.project.id,
        toProjectId: other.id,
        fromNumber: 1,
        toNumber: 2,
      },
    });
  });

  it("is a silent no-op within the same project", async () => {
    const issue = await create(tenant.project.id, "Stay put");
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => {
      seen.push(p);
    });
    const result = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });
    off();
    expect(result).toEqual(issue);
    expect(seen).toEqual([]);
  });

  it("refuses a viewer and changes nothing", async () => {
    const issue = await create(tenant.project.id, "Viewer cannot move");
    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: other.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored).toMatchObject({ projectId: tenant.project.id, number: issue.number });
  });

  it("moves the search index entry to the target project", async () => {
    const issue = await create(tenant.project.id, "Zebra searchable");
    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: other.id,
    });
    const query = (projectId: Project["id"]) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Zebra",
        kinds: ["issue"],
        projectId,
        limit: 25,
        cursor: null,
      });
    expect((await query(other.id)).total).toBe(1);
    expect((await query(tenant.project.id)).total).toBe(0);
  });

  it("applies the target project's issue quota", async () => {
    const free = await createTenant("movequota", "free");
    const target = await projectService.createProject(free.actors.owner, {
      orgId: free.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let n = 1; n <= 100; n += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, target.id, { title: `Seed ${n}` }),
        free.actors.member.userId,
        n,
      );
    }
    const issue = await issueService.createIssue(
      free.actors.member,
      issueInput(free.org.id, free.project.id, { title: "Does not fit" }),
    );
    await expect(
      issueService.moveIssueToProject(free.actors.member, {
        orgId: free.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toThrow(/allows no more issues/);
    const stored = await issueRepo.findIssueById(free.org.id, issue.id);
    expect(stored?.projectId).toBe(free.project.id);
  });
});
EOF
